/*
 * A087484  Least hypotenuse of a primitive Pythagorean triangle with inradius
 *          n.
 * https://oeis.org/A087484
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 10, u16 n <= 254, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   gcd
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Least hypotenuse c of a primitive Pythagorean triangle with
 * inradius r = n.  For a primitive triple generated by
 * Euclid's formula (m > k, gcd(m,k)=1, m−k odd),
 * the inradius is r = k(m−k).  We enumerate all divisor pairs
 * (k, d) of r with d = m−k, requiring d odd and gcd(k,d)=1,
 * then compute c = (k+d)^2 + k^2 and take the minimum.
 */

#include "../utils/gcd.h"

static seq_t _compute_hypotenuse(seq_t k, seq_t d)
{
    /* d must be odd (ensures m and k have opposite parity) */
    if ((d & 1) == 0) return 0;
    if (gcd(k, d) != 1U) return 0;

    seq_t m = k + d;
    return m * m + k * k;
}

seq_t a(idx_t n)
{
    if (n == 0) return 0U;          /* offset is 1 – undefined for n==0 */

    seq_t r   = (seq_t)n;           /* inradius */
    seq_t best = 0U;                /* 0 indicates not found yet */

    for (seq_t d = 1; d * d <= r; ++d) {
        if (r % d == 0) {
            seq_t k = d;
            seq_t e = r / d;
            seq_t w = _compute_hypotenuse(k, e);
            if (w != 0 && (best == 0 || w < best)) best = w;

            if (d != e) {           /* consider the swapped pair */
                k = e;
                e = d;
                w = _compute_hypotenuse(k, e);
                if (w != 0 && (best == 0 || w < best)) best = w;
            }
        }
    }
    return best;                     /* will be 0 only if no primitive exists */
}
